import { MakeLogicType, kea, path, selectors } from 'kea'

import { organizationLogic } from 'scenes/organizationLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface interProjectCopyLogicValues {
    canCopyToProject: boolean
    copyToProjectDisabledReason: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface interProjectCopyLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        canCopyToProject: (currentOrganization: null | import('../../types').OrganizationType) => boolean
        copyToProjectDisabledReason: (
            currentOrganization: null | import('../../types').OrganizationType
        ) => string | null
    }
}

export type interProjectCopyLogicType = MakeLogicType<
    interProjectCopyLogicValues,
    {},
    Record<string, any>,
    interProjectCopyLogicMeta
>

export const interProjectCopyLogic = kea<interProjectCopyLogicType>([
    path(['scenes', 'resource-transfer', 'interProjectCopyLogic']),

    selectors({
        // Having somewhere to copy to is the only requirement. Don't gate this on a feature flag: the transfer
        // API is ungated and the docs describe copying as generally available, so a flag that resolves false
        // (for example one aggregated on a group type that isn't attached at evaluation time) silently removes
        // a shipped feature.
        canCopyToProject: [
            () => [organizationLogic.selectors.currentOrganization],
            (currentOrganization: null | import('../../types').OrganizationType): boolean =>
                (currentOrganization?.teams?.length ?? 0) > 1,
        ],
        copyToProjectDisabledReason: [
            () => [organizationLogic.selectors.currentOrganization],
            (currentOrganization: null | import('../../types').OrganizationType): string | null => {
                if (!currentOrganization) {
                    return 'Loading projects'
                }
                if ((currentOrganization.teams?.length ?? 0) > 1) {
                    return null
                }
                return 'Your organization only has one project. Create another project to copy resources into it.'
            },
        ],
    }),
])
